                        }
                    }

                    // For each combination of nextS1 and nextS2, add to transition
                    for (int ns1 : nextS1) {
                        for (int ns2 : nextS2) {
                            int to = ns1 * stateCount + ns2;
                            trans[from][to] = (trans[from][to] + 1) % MOD;
                        }
                    }
                }
            }
        }

        // Initial state: (0, 0) = state 0
        // After m characters, we need to be in state (0, 0)
        // Answer = (M^m)[0][0]

        // Matrix exponentiation
        long[][] result = matrixPower(trans, m, totalStates);
        System.out.println(result[0][0] % MOD);
    }

    static long[][] matrixPower(long[][] base, long exp, int size) {
        long[][] result = new long[size][size];
        for (int i = 0; i < size; i++) {
            result[i][i] = 1;
        }

        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = matrixMultiply(result, base, size);
            }
            base = matrixMultiply(base, base, size);
            exp >>= 1;
        }

        return result;
    }

    static long[][] matrixMultiply(long[][] A, long[][] B, int size) {
        long[][] C = new long[size][size];
        for (int i = 0; i < size; i++) {
            for (int k = 0; k < size; k++) {
                if (A[i][k] == 0) continue;
                for (int j = 0; j < size; j++) {
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
                }
            }
        }
        return C;
    }
